<?php
require_once __DIR__.'/Accounts.php';
class SaaSRoles {
    public static function decision($project,$member,$feature,$mode){if(($member['role']??'')==='project_admin')return null;$s=SaaSAccounts::snapshot();$pid=$project['id'];$roleId=$s['role_assignments'][$pid][$member['username']]??null;if(!$roleId)return null;$role=$s['roles'][$pid][$roleId]??null;if(!$role)return false;$allowed=$role[$mode]??[];return in_array($feature,$allowed,true);}
    public static function manage($project){$member=SessionIdentity::member($project);if(!isMainAdmin()&&(!$member||($member['role']??'')!=='project_admin'))throw new RuntimeException('تعریف نقش فقط برای ادمین اصلی پروژه مجاز است.');}
    public static function save($project,$input){self::manage($project);$id=$input['role_id']??'';$name=trim($input['name']??'');if(!SaaSAccounts::validId($id)||$name==='')throw new RuntimeException('نام و شناسهٔ نقش معتبر نیست.');$known=array_keys(FeatureFlags::getCatalog());$view=array_values(array_unique((array)($input['view']??[])));$use=array_values(array_unique((array)($input['use']??[])));if(array_diff($view,$known)||array_diff($use,$view))throw new RuntimeException('مجوز اجرا باید مجوز مشاهده هم داشته باشد.');(new SaaSAccounts())->change(function(&$s)use($project,$id,$name,$view,$use){$s['roles'][$project['id']][$id]=['id'=>$id,'name'=>$name,'view'=>$view,'use'=>$use];});}
    public static function assign($project,$username,$role){self::manage($project);$found=false;foreach($project['users']??[] as $member)if($member['username']===$username&&($member['role']??'')!=='project_admin')$found=true;if(!$found)throw new RuntimeException('عضو عادی پروژه یافت نشد؛ نقش ادمین اصلی از این مسیر تغییر نمی‌کند.');(new SaaSAccounts())->change(function(&$s)use($project,$username,$role){if(!isset($s['roles'][$project['id']][$role]))throw new RuntimeException('نقش یافت نشد.');$s['role_assignments'][$project['id']][$username]=$role;});}
}
